  intro: {
    purpose: 'This document specifies, in business terms, what the Sky LIS product does: the two portals, their modules and pages, the data each page handles, the actions users can take, the rules the system enforces, and the end-to-end workflows that connect the pages. It is the reference for product owners, laboratory domain experts, designers, developers and testers, and the baseline for acceptance.',
    scope: 'Sky LIS is a cloud, subscription-based, multi-tenant Laboratory Information System operated by National Technology. The Super Admin Portal serves National Technology staff; the Client Portal serves each subscribed laboratory (tenant) with its branches and staff. This SRS describes the full target product and marks the subset delivered in Release 1.',
    outOfScope: ['Installation, hosting and infrastructure procedures.', 'Detailed visual design (the prototypes are the UI reference).', 'Quality control, outsourcing to external laboratories, SMS campaigns and inter-branch transfer modules beyond the placeholders noted here.', 'Country-specific regulatory reporting.'],
    conventions: [['Page ID', 'CP-nn for Client Portal pages, SA-nn for Super Admin pages. IDs are stable.'], ['Release', 'R1 = included in Release 1 (prototypes v2.1 / v3.1). R2 = later release (full-scope prototypes v2 / v3).'], ['Business rule', 'BR-nn, listed in section 9 and referenced from pages and workflows.'], ['Workflow', 'WF-nn, step tables with actor, action and system response.'], ['Requirement reference', 'Codes such as REG-005 refer to the functional requirements in LIS-RS-001.']]
  },

  business: {
    context: 'National Technology replaces its on-premise LDM laboratory system with Sky LIS, a cloud product sold by subscription. A laboratory subscribes online, receives its own portal address and an independent copy of the global laboratory master data, and runs its daily operation — reception, samples, results, printing, money — from the Client Portal across its branches. National Technology operates the platform from the Super Admin Portal: client lifecycle, plans and wallets, global master data, libraries and platform configuration.',
    goals: ['Let a laboratory start operating within a day of subscribing, with a ready catalogue and price lists.', 'Preserve every operational safeguard laboratories rely on: duplicate-patient protection, the sample Received gate, verified-only printing, delta and panic alerts, contract-correct pricing, auditable money movements.', 'Serve reception, bench, sign-off, accounts and administration personas from one bilingual, responsive workspace.', 'Connect analysers and PCR instruments and release normal results automatically where the laboratory chooses to.', 'Give National Technology central control of master data, subscriptions and support.'],
    actors: [
      ['Super Admin / Operations Admin', 'National Technology staff: clients, plans and wallets, admin users and roles, global master data, libraries, platform parameters, sessions and audit.'],
      ['Lab Administrator', 'Owns the tenant configuration: branches, roles, users, catalogue copy, payers and prices, payment methods, parameters, analysers and automation.'],
      ['Reception clerk / cashier', 'Registers patients and visits, orders services, answers preparation questions, collects money, prints labels, job orders, receipts and verified reports, closes the drawer.'],
      ['Phlebotomist / courier', 'Collects samples in the laboratory or at home, is recorded as collector, brings lab-to-lab samples.'],
      ['Technician / chemist', 'Receives samples, runs the worklist, enters or imports results, reviews, rejects unfit samples.'],
      ['Unit head / responsible doctor', 'Verifies (e-signs) results, handles abnormal, panic and delta-flagged results, releases reports, owns auto-verification rules.'],
      ['Microbiologist / pathologist', 'Enters culture results and formatted-text reports.'],
      ['Accounts officer', 'Price lists and contracts, refunds and transfers, claims, financial reports.'],
      ['Integration engineer', 'Analyser definitions and mappings, site agent, PCR kits.'],
      ['Patient / payer / referring doctor', 'External parties receiving quotes, receipts, reports and claims.']
    ],
    identifiers: [['Patient No.', 'Permanent file number, auto-generated, never changes (P0004912).'], ['Accession', 'Visit number: date-based sequence per tenant (2610080001).'], ['Sample ID', 'Unique barcode number per tube, never reused (S2610080001).'], ['Booking No. / Batch No.', 'Home-visit booking and batch (batch / lab-to-lab) grouping numbers.'], ['Print list No. / Claim No. / Receipt No.', 'Numbers printed on reports, claims and receipts.']],
    releaseSummary: 'Release 1 delivers the cross-cutting platform plus every page that existed in the first prototypes with its enhancements (Client Portal v2.1) and the complete operator portal except the integration library (Super Admin v3.1). Release 2 adds the new client pages and the integration, automation and quality-control modules. In Release 1 registration omits the hospital Location/Department and Room fields and captures the payment before saving; samples are received automatically on save because the sample pages arrive in Release 2.'
  },

